from pysat.solvers import Solver
from pysat.formula import CNF
import time, sys
n=12
def var(i,j,k): return 1+(i*n+j)*n+k
cnf=CNF()
# exact cell pairwise
for i in range(n):
  for j in range(n):
    if i==j:
      cnf.append([var(i,j,i)])
      # omit negatives exact at most with positive? add cell atmost below
    else:
      cnf.append([var(i,j,k) for k in range(n) if k!=i and k!=j]) # no operands
      cnf.append([-var(i,j,i)]); cnf.append([-var(i,j,j)])
    for a in range(n):
      for b in range(a+1,n): cnf.append([-var(i,j,a),-var(i,j,b)])
# row/col at most (at least follows from n cells maybe, but add atleast)
for i in range(n):
  for k in range(n):
    cnf.append([var(i,j,k) for j in range(n)])
    for j1 in range(n):
      for j2 in range(j1+1,n): cnf.append([-var(i,j1,k),-var(i,j2,k)])
for j in range(n):
  for k in range(n):
    cnf.append([var(i,j,k) for i in range(n)])
    for i1 in range(n):
      for i2 in range(i1+1,n): cnf.append([-var(i1,j,k),-var(i2,j,k)])
# anti-comm no same for off diag
for i in range(n):
  for j in range(i+1,n):
    for k in range(n): cnf.append([-var(i,j,k), -var(j,i,k)])
# QG3 skip impossible a or b? all
for i in range(n):
  for j in range(n):
    for a in range(n):
      for b in range(n):
        cnf.append([-var(i,j,a), -var(j,i,b), var(a,b,i)])
print('base clauses', len(cnf.clauses), flush=True)
# row0 11-cycle
sigma=[0]+list(range(2,12))+[1]
assumps=[var(0,j,sigma[j]) for j in range(n)]
print('sigma',sigma, flush=True)
start=time.time()
with Solver(name='cadical195', bootstrap_with=cnf.clauses) as s:
    res=s.solve(assumptions=assumps)
    print('res',res,'time',time.time()-start, flush=True)
    if res:
      model=set(l for l in s.get_model() if l>0)
      grid=[]
      for i in range(n):
        row=[]
        for j in range(n):
          for k in range(n):
            if var(i,j,k) in model:
              row.append(k); break
        print(row, flush=True); grid+=row
      print(grid, flush=True)
